#!/usr/bin/env bash
# Droit à l'image : le formulaire en ligne a sa page, « Mon droit à l'image » (/profil/droit-a-l-image).
# - lien dans le menu du compte (sous « Mon profil ») ; le profil montre le statut et un bouton vers la page,
#   mis en avant tant qu'aucune autorisation n'est enregistrée ;
# - majorité non renseignée : la page explique pourquoi le formulaire n'apparaît pas et quoi faire ;
# - guide, doc admin et doc dev à jour ; tests e2e d'accès.
# Pas de migration. Prérequis : apply-page-introuvable.sh.
# Usage (racine du repo) : bash apply-droit-image-acces.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/app/(public)/profil/page.tsx" 2>/dev/null | grep -qF "ImageConsentSummary"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "PageIntrouvable" "apps/web/src/app/not-found.tsx" 2>/dev/null || { echo "lancez d'abord apply-page-introuvable.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/droit-image-d-un-mineur.mdx" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" "apps/web/content/docs/guide/mon-profil.mdx" "apps/web/src/app/(public)/profil/page.tsx" "apps/web/src/features/app-shell/UserMenu.tsx" "apps/web/src/features/image-consent/MyAppearances.tsx" "apps/web/src/features/image-consent/OnlineConsentForm.tsx" "apps/web/src/features/tours/definitions/membre.profil.ts" "e2e/droit-a-l-image-parent-pages.spec.ts")
CREATED=("apps/web/src/app/(public)/profil/droit-a-l-image/page.tsx" "apps/web/src/features/image-consent/ImageConsentSummary.tsx" "e2e/droit-a-l-image-acces.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/src/app/(public)/profil/droit-a-l-image" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "ImageConsentSummary" "apps/web/src/app/(public)/profil/page.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/app/(public)/profil/droit-a-l-image"
